mapper.select:
SELECT * FROM spd_receive_main
WHERE del_flag = #{delFlag}

    AND receive_code LIKE CONCAT('%', #{query.receiveCode}, '%')


    AND acceptance_code = #{query.acceptanceCode}


    AND warehouse_id = #{query.warehouseId}


    AND receive_status = #{query.receiveStatus}


    AND create_time >= #{query.createTimeStart}


    AND create_time <= #{query.createTimeEnd}

ORDER BY create_time DESC
